package org.apache.commons.jxpath.ri.model.jdom;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.util.Locale;

import org.apache.commons.jxpath.ri.model.NodePointer;
import org.jdom2.Attribute;
import org.jdom2.Document;
import org.jdom2.Element;
import org.junit.Test;

public class CompareChildNodePointersTests {

    @Test
    public void testCompareChildNodePointers_AttributeBeforeChild_ReturnsNegative() {
        // Setup a root element with one attribute and one child element
        Element root = new Element("root");
        Attribute attr = new Attribute("attr1", "value");
        root.setAttribute(attr);

        Element child = new Element("child");
        root.addContent(child);

        // Create root pointer
        NodePointer rootPointer = new JDOMNodePointer((Object) root, Locale.ENGLISH);
        // Pointers for attribute and child under the same root
        NodePointer attrPointer = new JDOMNodePointer((NodePointer) rootPointer, (Object) attr);
        NodePointer childPointer = new JDOMNodePointer((NodePointer) rootPointer, (Object) child);

        // Use a comparator instance to invoke the method
        JDOMNodePointer comparator = new JDOMNodePointer((NodePointer) rootPointer, (Object) root);

        int result = comparator.compareChildNodePointers(attrPointer, childPointer);
        // Attributes should come before child nodes
        assertTrue("Attribute should be before child node", result < 0);
    }

    @Test
    public void testCompareChildNodePointers_AttributeComparedToSameAttribute_ReturnsZero() {
        // Setup a root element with an attribute
        Element root = new Element("root");
        Attribute attr = new Attribute("attr1", "value");
        root.setAttribute(attr);

        // Create root pointer
        NodePointer rootPointer = new JDOMNodePointer((Object) root, Locale.ENGLISH);
        // Pointers for the same attribute
        NodePointer attrPointer1 = new JDOMNodePointer((NodePointer) rootPointer, (Object) attr);
        NodePointer attrPointer2 = new JDOMNodePointer((NodePointer) rootPointer, (Object) attr);

        // Comparator
        JDOMNodePointer comparator = new JDOMNodePointer((NodePointer) rootPointer, (Object) root);

        int result = comparator.compareChildNodePointers(attrPointer1, attrPointer2);
        assertEquals("Same underlying attribute pointers should be equal", 0, result);
    }

    @Test
    public void testCompareChildNodePointers_ChildBeforeAttribute_ReturnsPositive() {
        // Setup a root element with an attribute and a child
        Element root = new Element("root");
        Attribute attr = new Attribute("attr1", "value");
        root.setAttribute(attr);

        Element child = new Element("child");
        root.addContent(child);

        // Pointers
        NodePointer rootPointer = new JDOMNodePointer((Object) root, Locale.ENGLISH);
        NodePointer attrPointer = new JDOMNodePointer((NodePointer) rootPointer, (Object) attr);
        NodePointer childPointer = new JDOMNodePointer((NodePointer) rootPointer, (Object) child);

        // Comparator
        JDOMNodePointer comparator = new JDOMNodePointer((NodePointer) rootPointer, (Object) root);

        int result = comparator.compareChildNodePointers(childPointer, attrPointer);
        // Child should come after attribute, so result should be positive when pointer1 is child
        assertTrue("Child should be after attribute", result > 0);
    }

    @Test(expected = IllegalStateException.class)
    public void testCompareChildNodePointers_InvalidParentThrowsIllegalState() {
        // Create a document (non-Element as parent)
        Element root = new Element("root");
        Document doc = new Document(root);
        NodePointer docPointer = new JDOMNodePointer((Object) doc, Locale.ENGLISH);

        // Create two child-like nodes under a non-Element parent (invalid scenario)
