    }

    @Test
    public void testDoubleValueFromUnparsableString() {
        double value = InfoSetUtil.doubleValue("not-a-number");
        assertTrue(Double.isNaN(value));
    }

    @Test
    public void testDoubleValueFromUnsupportedObject() {
        Object obj = new Object();
        double value = InfoSetUtil.doubleValue(obj);
        assertTrue(Double.isNaN(value));
    }

    @Test
    public void testDoubleValueIsIdempotent() {
        double first = InfoSetUtil.doubleValue(5);
        double second = InfoSetUtil.doubleValue(first);
        assertEquals(first, second, 0.0);
    }
